-- B-tree index for date-range queries with tenant scoping
-- Use leading equality column then range column for best selectivity
CREATE INDEX CONCURRENTLY IF NOT EXISTS {{index_name}}
  ON {{table_name}} ({{tenant_column}}, {{date_column}} DESC);

-- Verify planner uses it
EXPLAIN (ANALYZE, BUFFERS)
SELECT *
FROM {{table_name}}
WHERE {{tenant_column}} = $1
  AND {{date_column}} >= now() - interval '7 days'
ORDER BY {{date_column}} DESC
LIMIT 100;
